def compress(nums: list[int]) -> str:
    """See SPEC.md."""
    parts: list[str] = []
    run: list[int] = []

    def flush() -> None:
        if len(run) >= 3:
            a, b = run[0], run[-1]
            if a < 0:
                parts.append(f"({a})-({b})")
            else:
                parts.append(f"{a}-{b}")
        else:
            parts.extend(str(n) for n in run)
        run.clear()

    for n in sorted(set(nums)):
        if run and n == run[-1] + 1:
            run.append(n)
        else:
            flush()
            run.append(n)
    flush()
    return ",".join(parts)

